            "translation": "醉意朦胧中我拨亮油灯细看心爱的宝剑，恍惚从梦中醒来，耳畔回荡着各个军营连成一片的雄壮号角声。",
            "explanation": "【挑灯看剑】拨旺灯芯端详宝剑，写英雄闲居乡野却念念不忘沙场杀敌。【吹角连营】各营地吹响军号，气势连绵。"
