            "translation": "喜欢登上高楼，为了写出新颖的词曲，没有忧愁却偏偏勉强硬要说愁。",
            "explanation": "【强说愁】勉强表达装模作样的感伤，真实勾勒出青年文人的浪漫幼稚之态。"
