            "translation": "柳枝上的柳絮随风吹拂越来越稀少，然而放眼天涯海角，哪里没有青翠碧绿的芳草呢！",
            "explanation": "【枝上柳绵吹又少】春光渐逝之惋惜。【天涯何处无芳草】由自然景物转为超旷豁达的人生态度，千古名句。"
