        "translation": "重重叠叠的巍峨青山终究遮挡不住江水的前行，江水奔腾呼啸，毕竟还是向着东方浩浩荡荡奔流而去！",
        "explanation": "【青山遮不住，毕竟东流去】千古警策名句，借江水奔腾不可阻挡，喻历史潮流与抗金收复失地正义大势之不可逆转。"
