            "translation": "想要捎寄一封色彩绚丽的信笺和思念的短书，可是山高路远水域辽阔，又有谁知道你究竟身在何方呢？",
            "explanation": "【彩笺兼尺素】精致的诗笺与书信。【知何处】音讯隔绝，惆怅无极。"
